$_MODULE['<{ntbackupandrestore}prestashop>faq_51452b6d1f8511cf289eb01753eda3bb'] = 'Automatiseringen av 2N görs dagligen';
$_MODULE['<{ntbackupandrestore}prestashop>faq_42027eaa203032a09ccc5048897c677c'] = 'Automatiseringen av 2N verkar inte fungerar längre, vad kan jag göra?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_ffebb8fcef9bdccc3aeac353e6d78be7'] = 'Försök spara den igen';
$_MODULE['<{ntbackupandrestore}prestashop>faq_41906c69303e903c986fde8f7cb34665'] = 'Säkerhetskopieringen avslutades med ett fel som indikerar att det inte finns tillräckligt med utrymme för säkerhetskopieringen, men jag vet att det finns. Varför har jag det här felet?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_8bdbb9087cc2864414759889f6d22307'] = 'Det här felet kan bero på en gräns för din server. Vissa Server (32 bitar) kommer inte att tillåta att säkerhetskopian är av mer än 2 GB. I det här fallet kan du använda alternativet Avancerat för att begränsa storleken på säkerhetskopian. Din säkerhetskopia kommer att skäras i mindre delar som kommer att accepteras av din server. Du kan till exempel välja 1500 som storleksgräns för säkerhetskopians filstorlek. Var uppmärksam på att alla delar är obligatoriska om du vill återställa din butik.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_afde1c7273735610102d9f166386b91e'] = 'Var kan jag hitta säkerhetskopian på min server?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_c99296863a8cfebedbf941a80b149eb3'] = 'Du hittar din säkerhetskopia i katalogen modules/ntbackupandrestore/backup/som standard, eller i den katalog som du konfigurerade i Avancerad konfiguration.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_6162f1ad35f8d68d2ad18e65d6af12ca'] = 'Var hittar jag databasdumpen i min säkerhetskopia?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_259f134b1c3cb0f4211d27812fb4f339'] = 'När du skapar en fullständig säkerhetskopia sparas databasen med alla andra filer i säkerhetskopian. Om du vill kontrollera, untar din backup-fil på din dator, kan du hitta dumpen. SQL i katalogen modules/Ntbackupandrestore/backup/';
$_MODULE['<{ntbackupandrestore}prestashop>faq_d50856eaf5567a344aafac6b6629a581'] = 'Hur kan jag kontrollera att min säkerhetskopia är giltig?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_d2a25247fc786e9f6a27212ee9aed0b8'] = 'Det bästa sättet att se till att din säkerhetskopia är giltig, är att försöka återställa den någon annanstans. Till exempel på en ny domän och ny databas eller på din dator med WAMP, MAMP, easyphp eller andra lokala serverprogram mjukvaror.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_b26bae87fdb843d75a120d12fe51ffa6'] = 'Hur kan jag återställa min säkerhetskopia?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_84d3c56657e5438d10f92c3d36c5cf8b'] = 'För att återställa din säkerhetskopia måste du:';
$_MODULE['<{ntbackupandrestore}prestashop>faq_261aa829c8bd1bd4216bf09dc76f7326'] = 'Välj var du handlar kommer att återställas. Antingen på en ny plats (ny domän och ny databas) för en kopia/flytta eller i roten på din nuvarande butik för dess ersättare.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0c02578d80e75b15e3c2fafda964bfe4'] = 'Sätt ditt säkerhetskopierings-och återställnings skript på den valda platsen';
$_MODULE['<{ntbackupandrestore}prestashop>faq_967e66ec729f29106f185bf0e5c9c267'] = 'Komma åt återställningsskriptet med din webbläsare';
$_MODULE['<{ntbackupandrestore}prestashop>faq_96c158c212b69d93f4bf51a208b7c6b0'] = 'Fyll i autentiseringsuppgifterna för den databas där data kommer att återställas.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_3438a63edfc1456e8bff9b8a75f0f8c2'] = 'Valfritt: om det behövs konfigurerar du de avancerade alternativen';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0b20e24f98a55bf66d6fe76363284591'] = 'Starta restaureringen. Var uppmärksam på att filer från din säkerhetskopia kommer att skriva över potentiella befintliga filer och databasen kommer att ersättas av databasen från din säkerhetskopia.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_6510898b2f7a8fa6fe8aeafb9ea5ca4d'] = 'För att återställa min butik, måste jag installera en tom Prestashop, först?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_2f8b950c8cb11678dd68bd1050f15034'] = 'Du behöver inte installera en tom Prestashop för att återställa. Du behöver bara din backup fil och restaurering script.';
